mapper.select:
select p.ID,p.UserId,d.DrugsName,d.DrugsFormat,pd.Amount,d.DrugsUnit,d.DrugsPrice, (d.DrugsPrice*pd.Amount) as SUM,d.ManuFacturer,pd.DrugsUsage,pd.Dosage,pd.State,r.RealName, r.Gender,r.Age,ps.PayTime,p.prescriptionState,r.caseNumber from Drugs d ,Prescription p,Prescriptiondetailed pd, MedicalRecord m , Register r, PatientCosts ps where pd.PrescriptionID = p.id and pd.drugsid = d.id and m.ID = p.MedicalID and m.RegistID = r.ID
and m.CaseNumber = #{CaseNumber}
and pd.State = #{State}
and pd.State!=2
